package io.knowledgebrain.media;
import java.time.*;import java.util.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.flywaydb.core.Flyway;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.server.ResponseStatusException;
import static org.assertj.core.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_MEDIA_DATABASE_URL",matches=".+")
class MediaStoreIntegrationTest {
 PGSimpleDataSource source;MediaStore store;JdbcTemplate jdbc;UuidV7 ids=new UuidV7(Clock.systemUTC());String trace="a".repeat(32);
 @BeforeEach void setup(){source=new PGSimpleDataSource();source.setURL(System.getenv("BRAIN_TEST_MEDIA_DATABASE_URL"));source.setUser("brain_media");source.setPassword(System.getenv("BRAIN_TEST_MEDIA_DATABASE_PASSWORD"));Flyway.configure().dataSource(source).locations("classpath:db/migration").load().migrate();store=new MediaStore(source,Clock.systemUTC());jdbc=new JdbcTemplate(source);}
 MediaInput.Upload input(long size){return new MediaInput.Upload("test.pdf","application/pdf",size,"a".repeat(64));}
 @Test void immutableCompletionOwnSpaceAndAtomicOutbox(){UUID space=ids.next(),actor=ids.next();var pending=store.create(space,actor,input(10),trace);assertThat(pending.mediaId().version()).isEqualTo(7);assertThatThrownBy(()->store.available(space,pending.mediaId())).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->store.get(ids.next(),pending.mediaId())).isInstanceOf(ResponseStatusException.class);var done=store.complete(space,pending.mediaId(),actor,"v1",trace);assertThat(done.version()).isEqualTo(2);assertThat(store.complete(space,pending.mediaId(),actor,"v2",trace)).isEqualTo(done);store=new MediaStore(source,Clock.systemUTC());assertThat(store.stored(space,pending.mediaId()).objectVersion()).isEqualTo("v1");assertThat(jdbc.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregateid=?",Integer.class,pending.mediaId())).isEqualTo(2);assertThatThrownBy(()->store.create(space,actor,input(10),"bad")).isInstanceOf(IllegalArgumentException.class);assertThat(store.list(space,null,100).items()).hasSize(1);}
 @Test void concurrentReservationsCannotExceedGuestQuota() throws Exception {UUID space=ids.next(),actor=ids.next();try(var workers=Executors.newVirtualThreadPerTaskExecutor()){var start=new CountDownLatch(1);var futures=new ArrayList<Future<Integer>>();for(int n=0;n<12;n++)futures.add(workers.submit(()->{start.await();try{store.create(space,actor,input(MediaInput.MAX_FILE),trace);return 201;}catch(ResponseStatusException e){return e.getStatusCode().value();}}));start.countDown();var codes=new ArrayList<Integer>();for(var f:futures)codes.add(f.get(30,TimeUnit.SECONDS));assertThat(Collections.frequency(codes,201)).isEqualTo(10);assertThat(Collections.frequency(codes,409)).isEqualTo(2);}assertThat(store.list(space,null,100).items()).hasSize(10);}
}
